export const MESSAGES=Object.fromEntries(Object.keys(LANGUAGES).map(lang=>[lang,Object.fromEntries(entries.map(([key,en,ko,fr])=>[key,lang==='en'?en:lang==='ko'?ko:fr??key]))]));
let language='en';
export const getLanguage=()=>language;
export const locale=()=>locales[language];
export function readLanguage(storage){try{const value=storage?.getItem(LANGUAGE_KEY);return value==='kr'?'ko':Object.hasOwn(LANGUAGES,value)?value:'en';}catch{return 'en';}}
export function setLanguage(value,storage){language=value==='kr'?'ko':Object.hasOwn(LANGUAGES,value)?value:'en';try{storage?.setItem(LANGUAGE_KEY,language);}catch{}if(typeof document!=='undefined')document.documentElement.lang=language;return language;}
export const number=value=>new Intl.NumberFormat(locale()).format(value);
export function t(key,values={}){return (Object.hasOwn(MESSAGES[language],key)?MESSAGES[language][key]:String(key)).replace(/\{(\w+)\}/g,(match,name)=>Object.hasOwn(values,name)?typeof values[name]==='number'?number(values[name]):String(values[name]):match);}
export const count=(kind,n)=>t(`count.${kind}.${n===1?'one':'other'}`,{n});
export function formatDate(value){return value?new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')):t('Date non précisée');}
export function sourceNote(value){value=String(value??'');const match=value.match(/^Seules les positions explicitement attribuées à (.+) sont affichées\. Les passages partagés restent collectifs\.$/);return match?t('note.scoped',{dj:match[1]}):t(value);}
export function translateError(error){
 const message=String(error?.message??error);
 const set=message.match(/^Set (\d+) : (.*)$/);if(set)return t('Set {n} : {message}',{n:Number(set[1]),message:translateError(set[2])});
 for(const prefix of ['Repère temporel invalide','Ligne non reconnue'])if(message.startsWith(prefix+' : '))return t(prefix+' : {value}',{value:message.slice(prefix.length+3)});
 if(message==='Invalid URL'||message.includes('Invalid URL'))return t('Lien invalide. Utilise une adresse HTTPS complète.');
 return Object.hasOwn(MESSAGES.en,message)?t(message):t('Import impossible. Vérifie le fichier ou la tracklist.');
}
export function applyTranslations(root=globalThis.document){
 if(!root)return;
 root.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));
 for(const attr of ['aria-label','placeholder','title'])root.querySelectorAll(`[data-i18n-${attr}]`).forEach(el=>el.setAttribute(attr,t(el.getAttribute('data-i18n-'+attr))));
 if(typeof document!=='undefined'&&root===document){
  document.title=t('app.name');
  document.querySelectorAll('meta[name="description"],meta[property="og:description"],meta[name="twitter:description"]').forEach(meta=>meta.setAttribute('content',t('app.description')));
  document.querySelector('meta[property="og:locale"]')?.setAttribute('content',locale().replace('-','_'));
 }
}
